<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>2048</title>
  <style>
    * { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      background: #121212;
      color: #f0f0f0;
      font-family: system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
    }

    h1 {
      margin: 0 0 14px;
      font-size: 2rem;
      letter-spacing: .08em;
    }

    .hud {
      display: flex;
      align-items: center;
      gap: 12px;
      margin-bottom: 14px;
    }

    .score-panel {
      background: #1d1d1d;
      border: 1px solid #2d2d2d;
      border-radius: 10px;
      padding: 8px 14px;
      min-width: 110px;
      text-align: center;
    }

    .score-label {
      display: block;
      font-size: .72rem;
      text-transform: uppercase;
      letter-spacing: .12em;
      color: #9a9a9a;
    }

    #score {
      display: block;
      font-size: 1.35rem;
      font-weight: 700;
    }

    #reset {
      padding: 11px 16px;
      border: none;
      border-radius: 10px;
      background: #8f6b2f;
      color: #fff;
      font-weight: 700;
      cursor: pointer;
    }

    #reset:hover {
      background: #a47c37;
    }

    #board {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      grid-template-rows: repeat(4, 1fr);
      gap: 10px;
      width: min(90vw, 420px);
      height: min(90vw, 420px);
      background: #1d1d1d;
      border: 1px solid #2d2d2d;
      border-radius: 14px;
      padding: 10px;
    }

    .cell {
      display: flex;
      align-items: center;
      justify-content: center;
      border-radius: 10px;
      background: #282828;
      font-weight: 700;
      font-size: clamp(18px, 6vw, 34px);
      user-select: none;
    }

    .tile {
      color: #fff;
      background: #444;
    }

    .tile-2 { background: #4d4a3d; }
    .tile-4 { background: #5c563f; }
    .tile-8 { background: #8f6b2f; }
    .tile-16 { background: #a4572e; }
    .tile-32 { background: #b0413e; }
    .tile-64 { background: #c22f2f; }
    .tile-128 { background: #2f7d6d; }
    .tile-256 { background: #2f6d7d; }
    .tile-512 { background: #2f4f7d; }
    .tile-1024 { background: #5d2f7d; }
    .tile-2048 { background: #7d2f6b; }
    .tile-super { background: #191919; border: 1px solid #555; }

    .hint {
      margin-top: 12px;
      color: #888;
      font-size: .9rem;
    }
  </style>
</head>
<body>
  <h1>2048</h1>

  <div class="hud">
    <div class="score-panel">
      <span class="score-label">Score</span>
      <span id="score">0</span>
    </div>
    <button id="reset" type="button">New Game</button>
  </div>

  <div id="board" aria-label="2048 board"></div>
  <p class="hint">Arrow keys to move</p>

  <script>
    (function () {
      const SIZE = 4;
      let grid = createEmptyGrid();
      let scoreValue = 0;

      const boardEl = document.getElementById('board');
      const scoreEl = document.getElementById('score');

      function createEmptyGrid() {
        return Array.from({ length: SIZE }, () => Array(SIZE).fill(0));
      }

      function randomFloat() {
        const x = Math.random();
        return typeof x === 'number' && Number.isFinite(x) ? x : 0;
      }

      function chooseIndex(length) {
        let idx = Math.floor(randomFloat() * length);
        if (!Number.isFinite(idx) || idx < 0) idx = 0;
        if (idx >= length) idx = length - 1;
        return idx;
      }

      function addRandomTile() {
        const empties = [];
        for (let r = 0; r < SIZE; r++) {
          for (let c = 0; c < SIZE; c++) {
            if (grid[r][c] === 0) empties.push({ r, c });
          }
        }

        if (empties.length === 0) return;

        const value = randomFloat() < 0.9 ? 2 : 4;
        const idx = chooseIndex(empties.length);
        const cell = empties[idx];
        grid[cell.r][cell.c] = value;
      }

      function render() {
        boardEl.innerHTML = '';

        for (let r = 0; r < SIZE; r++) {
          for (let c = 0; c < SIZE; c++) {
            const value = grid[r][c];
            const cell = document.createElement('div');

            let className = 'cell';
            if (value !== 0) {
              className += ' tile';
              if (value > 0 && value <= 2048 && (value & (value - 1)) === 0) {
                className += ' tile-' + value;
              } else {
                className += ' tile-super';
              }
            }

            cell.className = className;
            cell.textContent = value === 0 ? '' : String(value);
            boardEl.appendChild(cell);
          }
        }

        scoreEl.textContent = String(scoreValue);
      }

      function reset() {
        grid = createEmptyGrid();
        scoreValue = 0;
        addRandomTile();
        addRandomTile();
        render();
      }

      function slideLine(line) {
        const tiles = line.filter(v => v !== 0);
        const result = [];
        let gain = 0;

        for (let i = 0; i < tiles.length; i++) {
          if (i + 1 < tiles.length && tiles[i] === tiles[i + 1]) {
            const merged = tiles[i] * 2;
            result.push(merged);
            gain += merged;
            i++;
          } else {
            result.push(tiles[i]);
          }
        }

        while (result.length < SIZE) result.push(0);
        return { line: result, gain };
      }

      function move(dir) {
        const direction = typeof dir === 'string' ? dir.toLowerCase() : '';
        if (direction !== 'left' && direction !== 'right' && direction !== 'up' && direction !== 'down') {
          return false;
        }

        const next = grid.map(row => row.slice());
        let moved = false;
        let totalGain = 0;

        for (let i = 0; i < SIZE; i++) {
          let original;
          let line;

          if (direction === 'left') {
            original = next[i].slice();
            line = original.slice();
          } else if (direction === 'right') {
            original = next[i].slice();
            line = original.slice().reverse();
          } else if (direction === 'up') {
            original = [next[0][i], next[1][i], next[2][i], next[3][i]];
            line = original.slice();
          } else {
            original = [next[0][i], next[1][i], next[2][i], next[3][i]];
            line = original.slice().reverse();
          }

          const slid = slideLine(line);
          totalGain += slid.gain;

          let finalLine = slid.line;
          if (direction === 'right' || direction === 'down') {
            finalLine = finalLine.slice().reverse();
          }

          if (!original.every((value, idx) => value === finalLine[idx])) {
            moved = true;
          }

          if (direction === 'left' || direction === 'right') {
            for (let c = 0; c < SIZE; c++) {
              next[i][c] = finalLine[c];
            }
          } else {
            for (let r = 0; r < SIZE; r++) {
              next[r][i] = finalLine[r];
            }
          }
        }

        if (!moved) {
          return false;
        }

        grid = next;
        scoreValue += totalGain;
        addRandomTile();
        render();
        return true;
      }

      function board() {
        return grid.map(row => row.slice());
      }

      function setBoard(arr) {
        grid = createEmptyGrid();

        if (arr && typeof arr.length === 'number') {
          for (let r = 0; r < SIZE; r++) {
            const row = arr[r];
            if (row && typeof row.length === 'number') {
              for (let c = 0; c < SIZE; c++) {
                const n = Number(row[c]);
                grid[r][c] = Number.isFinite(n) ? n : 0;
              }
            }
          }
        }

        scoreValue = 0;
        render();
      }

      function score() {
        return scoreValue;
      }

      window.game = {
        size: SIZE,
        reset: reset,
        move: move,
        board: board,
        setBoard: setBoard,
        score: score
      };

      document.getElementById('reset').addEventListener('click', reset);

      window.addEventListener('keydown', function (event) {
        const keyMap = {
          ArrowLeft: 'left',
          ArrowRight: 'right',
          ArrowUp: 'up',
          ArrowDown: 'down'
        };

        const direction = keyMap[event.key];
        if (direction) {
          event.preventDefault();
          move(direction);
        }
      });

      reset();
    })();
  </script>
</body>
</html>
